{
 "content": "def transform(grid):
    g = [list(row) for row in grid]
    h, w = len(g), len(g[0])
    cells = [(r, c) for r in range(h) for c in range(w) if g[r][c] == 8]
    if not cells:
        return g
    r0, r1 = min(r for r, _ in cells), max(r for r, _ in cells)
    c0, c1 = min(c for _, c in cells), max(c for _, c in cells)
    out = []
    for r in range(r0, r1 + 1):
        row = []
        for c in range(c0, c1 + 1):
            # Find a row with the same visible pattern outside the occlusion;
            # such duplicated rows encode the unobscured continuation.
            candidates = []
            for rr in range(h):
                if g[rr][c] == 8:
                    continue
                score = sum(g[rr][cc] == g[r][cc]
                            for cc in range(w) if g[r][cc] != 8 and g[rr][cc] != 8)
                candidates.append((score, rr))
            if candidates:
                best = max(score for score, _ in candidates)
                rr = min((rr for score, rr in candidates if score == best), key=lambda x: abs(x-r))
                row.append(g[rr][c])
            else:
                row.append(0)
        out.append(row)
    return out
